var 
i, count, maxlen, countA, k: integer;
c: char;
f: text;
begin
 assign(f,'C:\24.txt');
 reset(f);
 maxlen := 0;
 count := 0;
 countA := 0;
 k := 0;
 while not eof(f) do begin
 read(f, c);
 k := k + 1;
 if c <> 'A' then begin
 count := count + 1;
 if count > maxlen then maxlen := count;
 end
 else if countA = 0 then begin
 countA := 1;
 i := k;
 count := count + 1;
 if count > maxlen then maxlen := count;
 end
 else if countA = 1 then begin
 count := k - i;
 i := k;
 if count > maxlen then maxlen := count;
 end;
 end;
 writeln(maxlen);
end.
